/*
 * The coach's settings (DBU-07, DBU-11). Staff only. One Setting row per key, updated in place.
 *  - coachEmail: the address that hears about every learner message. Trimmed and lower-cased; blank
 *    puts the default back (a placeholder: the real address belongs here).
 *  - coachName: the name learners see on every page ("Ask Sam anything"). Trimmed, at most 60
 *    characters; blank means learners see "your coach".
 * A key the request leaves out is left as it is.
 */
(async () => {
  try {
    const R = Noodl.Records;
    const DEFAULT = 'coach@example.com';
    const put = async (key, value) => {
      const rows = await R.query('Setting', { key: { equalTo: key } }, { limit: 2, plain: true });
      if (rows.length) await R.save(rows[0].objectId, { value }, { className: 'Setting' });
      else await R.create('Setting', { key, value }, { plain: true });
    };
    const read = async (key) => {
      const rows = await R.query('Setting', { key: { equalTo: key } }, { limit: 2, plain: true });
      return rows[0] ? String(rows[0].value || '').trim() : '';
    };
    if (Inputs.coachEmail !== undefined && Inputs.coachEmail !== null) {
      const email = String(Inputs.coachEmail || '').trim().toLowerCase();
      const looksLikeEmail = email.length <= 254 && email.split('@').length === 2 && email.split('@')[1].includes('.') && !/\s/.test(email);
      if (email && !looksLikeEmail) { Outputs.why = 'That does not look like an email address. Check it and try again.'; Outputs.refuse(); return; }
      await put('coachEmail', email || DEFAULT);
    }
    if (Inputs.coachName !== undefined && Inputs.coachName !== null) {
      const name = String(Inputs.coachName || '').replace(/\s+/g, ' ').trim();
      if (name.length > 60) { Outputs.why = 'Keep the name under 60 characters: learners see it in the middle of sentences.'; Outputs.refuse(); return; }
      await put('coachName', name);
    }
    Outputs.coachEmail = (await read('coachEmail')) || DEFAULT;
    Outputs.coachName = await read('coachName');
    Outputs.done();
  } catch (e) {
    console.error('[dbu:saveCoachSettings]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
